#!/usr/bin/env bash
# Write a sourceable env file for MP4 recording (no giant export on screen).
set -euo pipefail
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=lib.sh
source "$SCRIPT_DIR/lib.sh"
verify_paths

OUT="${VERIFY_ROOT}/record-env.sh"
mkdir -p "$VERIFY_ROOT"
cat >"$OUT" <<EOF
# Generated by verify-sessionizer write-record-env.sh — do not commit.
export HOME='${VERIFY_HOME}'
export HERDR_PLUGIN_CONFIG_DIR='${VERIFY_CONFIG_DIR}'
export HERDR_BIN_PATH='${HERDR_BIN_PATH}'
export VERIFY_ROOT='${VERIFY_ROOT}'
export VERIFY_PROJECTS_DIR='${VERIFY_PROJECTS_DIR}'
export VERIFY_STATE='${VERIFY_STATE}'
export VERIFY_HERDR_TRACE='${VERIFY_HERDR_TRACE}'
export PATH='/tmp/fzf/bin:${HOME}/.local/bin:/exec-daemon:${VERIFY_REPO_ROOT}/dist:/usr/local/bin:/usr/bin:/bin'
cd '${VERIFY_REPO_ROOT}'
EOF
chmod 600 "$OUT"
echo "$OUT"
